package com.repairconnect.repository; import com.repairconnect.entity.*; import java.util.*; import org.springframework.data.jpa.repository.JpaRepository; public interface BookingRepository extends JpaRepository<Booking,Long>{List<Booking> findByCustomerUserEmailOrderByCreatedAtDesc(String email); List<Booking> findByProviderUserEmailOrderByCreatedAtDesc(String email); long countByStatus(BookingStatus status); boolean existsByProviderIdAndPreferredDateAndPreferredTimeAndStatusIn(Long providerId, java.time.LocalDate date, java.time.LocalTime time, Collection<BookingStatus> statuses);}